import unicodedata
from hmac import compare_digest
from typing import Dict, Optional, Union
from urllib.parse import quote, urlencode, urlparse

# Parameters that define the OTP itself or its label. They are generated by
# build_uri() from the core arguments and may never be supplied as extensions.
RESERVED_URI_PARAMETERS = frozenset(
    {
        "type",
        "otp_type",
        "secret",
        "issuer",
        "issuer_name",
        "algorithm",
        "digits",
        "period",
        "counter",
        "initial_count",
        "name",
        "label",
        "encoder",
    }
)

MAX_SECRET_LENGTH = 1024
MAX_LABEL_COMPONENT_LENGTH = 256
MAX_LABEL_LENGTH = 512
MAX_EXTENSION_KEY_LENGTH = 64
MAX_EXTENSION_VALUE_LENGTH = 1024

_PROHIBITED_CHARACTER_CATEGORIES = frozenset({"Cc", "Cf", "Cs"})


def _validate_text(value: str, field: str, max_length: int, allow_empty: bool = False) -> None:
    if not isinstance(value, str):
        raise ValueError("{} must be a string".format(field))
    if not allow_empty and not value:
        raise ValueError("{} must not be empty".format(field))
    if len(value) > max_length:
        raise ValueError("{} is too long".format(field))
    for character in value:
        if unicodedata.category(character) in _PROHIBITED_CHARACTER_CATEGORIES:
            raise ValueError("{} contains prohibited characters or invalid Unicode".format(field))
    try:
        value.encode("utf-8")
    except UnicodeEncodeError:
        # Do not chain the original exception: its message includes the value.
        raise ValueError("{} contains prohibited characters or invalid Unicode".format(field)) from None


def _quote_label_component(value: str) -> str:
    # A label is a path segment. Encode it with the same rules for the issuer
    # and account-name components, including "/" and ":" so those characters
    # cannot alter the path or the issuer:account separator.
    return quote(value, safe="", encoding="utf-8", errors="strict")


def _validate_image_url(value: str) -> None:
    try:
        image_uri = urlparse(value)
        has_userinfo = image_uri.username is not None or image_uri.password is not None
    except ValueError:
        raise ValueError("image must be an https URL without user information") from None
    if image_uri.scheme != "https" or not image_uri.netloc or not image_uri.path or has_userinfo:
        raise ValueError("image must be an https URL without user information")


def _validate_extra_parameters(parameters: Dict[str, str]) -> None:
    for key, value in parameters.items():
        if not isinstance(key, str):
            raise ValueError("Extension parameter names must be strings")
        if key.casefold() in RESERVED_URI_PARAMETERS:
            raise ValueError("Extension parameters may not override reserved otpauth parameters")
        _validate_text(key, "extension parameter name", MAX_EXTENSION_KEY_LENGTH)
        if not isinstance(value, str):
            raise ValueError("Extension parameter values must be strings")
        _validate_text(value, "extension parameter value", MAX_EXTENSION_VALUE_LENGTH, allow_empty=True)
        if key.casefold() == "image":
            _validate_image_url(value)


def build_uri(
    secret: str,
    name: str,
    initial_count: Optional[int] = None,
    issuer: Optional[str] = None,
    algorithm: Optional[str] = None,
    digits: Optional[int] = None,
    period: Optional[int] = None,
    **kwargs,
) -> str:
    """
    Returns the provisioning URI for the OTP; works for either TOTP or HOTP.

    This can then be encoded in a QR Code and used to provision the Google
    Authenticator app.

    For module-internal use.

    See also:
        https://github.com/google/google-authenticator/wiki/Key-Uri-Format

    :param secret: the hotp/totp secret used to generate the URI
    :param name: name of the account
    :param initial_count: starting counter value, defaults to None.
        If none, the OTP type will be assumed as TOTP.
    :param issuer: the name of the OTP issuer; this will be the
        organization title of the OTP entry in Authenticator
    :param algorithm: the algorithm used in the OTP generation.
    :param digits: the length of the OTP generated code.
    :param period: the number of seconds the OTP generator is set to
        expire every code.
    :param kwargs: non-reserved string parameters to add to the URI. Reserved
        parameters (type, secret, issuer, algorithm, digits, period, counter,
        and related aliases) must be passed through their core arguments.
    :returns: provisioning uri
    """
    _validate_text(secret, "secret", MAX_SECRET_LENGTH)
    _validate_text(name, "label account name", MAX_LABEL_COMPONENT_LENGTH)
    if issuer is not None:
        _validate_text(issuer, "label issuer", MAX_LABEL_COMPONENT_LENGTH)
        if len(issuer) + 1 + len(name) > MAX_LABEL_LENGTH:
            raise ValueError("label is too long")
    _validate_extra_parameters(kwargs)

    # initial_count may be 0 as a valid param
    is_initial_count_present = initial_count is not None

    # Handling values different from defaults
    is_algorithm_set = algorithm is not None and algorithm != "sha1"
    is_digits_set = digits is not None and digits != 6
    is_period_set = period is not None and period != 30

    otp_type = "hotp" if is_initial_count_present else "totp"
    base_uri = "otpauth://{0}/{1}?{2}"

    url_args: Dict[str, Union[None, int, str]] = {"secret": secret}

    label = _quote_label_component(name)
    if issuer is not None:
        label = _quote_label_component(issuer) + ":" + label
        url_args["issuer"] = issuer

    if is_initial_count_present:
        url_args["counter"] = initial_count
    if is_algorithm_set:
        url_args["algorithm"] = algorithm.upper()  # type: ignore
    if is_digits_set:
        url_args["digits"] = digits
    if is_period_set:
        url_args["period"] = period
    for k, v in kwargs.items():
        url_args[k] = v

    uri = base_uri.format(otp_type, label, urlencode(url_args).replace("+", "%20"))
    return uri


def strings_equal(s1: str, s2: str) -> bool:
    """
    Timing-attack resistant string comparison.

    Normal comparison using == will short-circuit on the first mismatching
    character. This avoids that by scanning the whole string, though we
    still reveal to a timing attack whether the strings are the same
    length.
    """
    s1 = unicodedata.normalize("NFKC", s1)
    s2 = unicodedata.normalize("NFKC", s2)
    return compare_digest(s1.encode("utf-8"), s2.encode("utf-8"))
